// Engine demo for pause time ("pause" in a storyboard, engine/shared/pause.js, 8 Nov 2026): on the living meadow road
// Phoenix waves and Reaper turns, Viking shouts HALT and the world stops (the grass, the clouds, a falling leaf, the
// butterflies, Phoenix mid-wave) while he walks across it in colour; then it carries on from where it stopped.
//   node storyboards/env/make-pause-demo.mjs -> pause-demo.json
//   node engine/render.mjs storyboards/env/pause-demo.json --stills 0.9,1.15,1.9,2.65,3.3 --draft
import { clip, write } from "../lib/clip.mjs";

const c = clip({ faces: "strong", lines: { sub: true, blink: false } }), { A, sfx } = c, END = 4.0;
const P0 = 1.05, P1 = 2.6;
// Phoenix waves (an arm swing that runs through the pause's start: held mid-way, finished after it)
A(0.6, "phx", "arm", { side: "R", pose: { o: [0.12, 1.0, 0.15] }, dur: 0.9, lead: false });
A(P1 + 0.2, "phx", "arm", { side: "R", pose: "rest", dur: 0.6 });
A(0.7, "rea", "look", { to: [-0.35, 0.1], dur: 0.6 });   // (a glance, not a turn: turned, his right sleeve went into Phoenix's wing)
// Viking: HALT, then across the frozen road and back into his place
c.say(0.55, "vik", "HALT!", 0.45, "excited", { sub: "HALT!", pos: 300 });   // above their heads: at the default y 1180 the three hid 27 % of it (main's caption-overlap FAIL, 9 Nov)
sfx(P0, "timestop", { gain: 0.9, reason: "the pause's power sound: the world stops" });
A(P0 + 0.15, "vik", "move", { to: [0.95, -1.0], dur: 1.2, steps: 2.2 });
sfx(P1, "timego", { gain: 0.8, reason: "the world starts again" });
const beats = c.beats([["all", 0, { pos: [0, 1.0, 3.6], look: [0, 0.75, -1.6], fov: 46 }]], END);
write(import.meta.url, {
  id: "pause-demo", title: "Pause time (engine demo)", idea: "Engine demo, not a clip: pause time (shared/pause.js)",
  fps: 30, look: "anime-pro", castLook: "sheet", profile: "short", loop: false, captionStyle: "kinetic", cleanStart: true,
  motion: { feet: 2, overlap: true, timing: true, solve: true }, rig: { hand: 2, eyes: 2, hold: 2 }, physics: true, animeTiming: true,
  set: { type: "env", env: "meadow-path", aperture: 0, lighting: 2, hatch: { boil: 0.25 }, cel: { at: 0.25 },
    life: { seed: 11, wind: { speed: 3.2, every: [1.2, 2.0], first: 0.2 }, clouds: { drift: 0.02, shadow: 0.32, speed: 4, scale: 16, near: 14 },
      butterflies: { n: 3, at: [[-0.75, 0.55, -0.7], [-0.2, 0.75, -1.3], [1.15, 0.5, -1.4]], r: 0.4, color: "#f0a23a" },
      leaves: { from: [[0.4, 2.2, -1.2], [-0.9, 2.4, -1.8]], n: 3 }, song: 1 } },
  music: { style: "warm", lowCut: 150, gain: 0.3 }, sound: { sfx: 0.7, ambience: 0.6, guard: true },
  hook: { show: ["vik", "phx", "rea"], hint: 0, what: "engine demo" },
  pause: [{ from: P0, to: P1, keep: ["vik"], origin: "vik" }],
  cast: [
    { id: "vik", character: "always-orders-potatoes/viking", at: [-0.95, -1.0], face: "camera", expr: "eager", follow: 0.3, seed: 2.1 },
    { id: "phx", character: "duo/phoenix", at: [-0.35, -2.0], face: "camera", expr: "happy", follow: 0.3, seed: 1.7, span: 0.2 },
    { id: "rea", character: "never-has-money/reaper", at: [0.95, -2.4], face: "camera", expr: "deadpan", follow: 0.3, seed: 3.3 },
  ],
  props: [], captions: c.captions, beats, visible: c.visible,
  notes: "Generated by storyboards/env/make-pause-demo.mjs (engine demo).",
});
